    "Script": "Scheduling = {
	init: async function (app, container) {
        api.addToMetaCache([
    {
        Name: "AppSecurity",
        Types: [
            [meta[AppSecurity/Role]],
            [meta[AppSecurity/User]]
        ]
    },
    {
        Name: "Workflow",
        Types: [
